import os
import re
from collections import defaultdict

REPO = "/bench/repo"
STORE_PREFIX = "github.com/usememos/memos/store"

# Persistent entity types (core domain structs, not Find/Update/Delete helpers)
ENTITIES = [
    "Memo", "User", "Attachment", "Reaction", "MemoRelation", "MemoShare",
    "Inbox", "IdentityProvider", "InstanceSetting", "UserSetting", "UserIdentity",
    # Supporting enums often used as entity fields
    "Visibility", "Role", "RowStatus", "InboxStatus", "MemoRelationType",
]

def go_package_name(content, filepath):
    m = re.search(r'^package\s+(\w+)', content, re.M)
    if not m:
        return None
    pkg = m.group(1)
    # Use import path style package id
    rel = os.path.relpath(filepath, REPO)
    parts = rel.split(os.sep)
    if parts[0] == "cmd":
        return f"github.com/usememos/memos/{parts[0]}/{parts[1]}"
    return f"github.com/usememos/memos/{os.path.dirname(rel).replace(os.sep, '/')}"

def is_store_layer(pkg_path):
    return pkg_path == STORE_PREFIX or pkg_path.startswith(STORE_PREFIX + "/")

entity_refs = {e: set() for e in ENTITIES}

for root, dirs, files in os.walk(REPO):
    # skip .git
    if '.git' in root.split(os.sep):
        continue
    for f in files:
        if not f.endswith('.go'):
            continue
        fp = os.path.join(root, f)
        try:
            with open(fp, 'r', errors='replace') as fh:
                content = fh.read()
        except Exception:
            continue

        pkg = go_package_name(content, fp)
        if not pkg or is_store_layer(pkg):
            continue

        imports_store = STORE_PREFIX in content or 'usememos/memos/store"' in content
        if not imports_store:
            continue

        for entity in ENTITIES:
            # Match store.Entity or *store.Entity or store.FindEntity etc.
            patterns = [
                rf'\bstore\.{entity}\b',
                rf'\*store\.{entity}\b',
            ]
            for pat in patterns:
                if re.search(pat, content):
                    entity_refs[entity].add(pkg)
                    break

# Sort by count
ranked = sorted(((e, len(pkgs), sorted(pkgs)) for e, pkgs in entity_refs.items()), key=lambda x: -x[1])

print("=== Ranked persistent entity external package references ===")
for entity, count, pkgs in ranked:
    if count > 0:
        print(f"{entity}: {count}")
        for p in pkgs:
            print(f"  - {p}")
        print()
PYEOF

