args.command:
perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my $STORE = "github.com/usememos/memos/store";
my @ENTITIES = qw(Memo User Attachment Reaction MemoRelation MemoShare Inbox IdentityProvider InstanceSetting UserSetting UserIdentity Visibility Role RowStatus InboxStatus MemoRelationType);
my %refs; $refs{$_} = {} for @ENTITIES;

sub pkg_path {
    my ($fp) = @_;
    $fp =~ s/^\Q$REPO\E\///;
    my @p = split /\//, $fp;
    pop @p; # filename
    if ($p[0] eq "cmd") { return "$STORE/../$p[0]/$p[1]"; }
    return "github.com/usememos/memos/" . join("/", @p);
}

sub is_store {
    my ($pkg) = @_;
    return 1 if $pkg eq $STORE || index($pkg, "$STORE/") == 0;
    return 0;
}

sub walk {
    my ($dir) = @_;
    opendir my $dh, $dir or return;
    while (my $e = readdir $dh) {
        next if $e eq "." || $e eq "..";
        my $path = "$dir/$e";
        if (-d $path) {
            next if $e eq ".git";
            walk($path);
        } elsif ($e =~ /\.go$/) {
            open my $fh, "<", $path or next;
            local $/; my $c = <$fh>; close $fh;
            $c =~ /^package\s+(\w+)/m or next;
            my $pkg = pkg_path($path);
            next if is_store($pkg);
            next unless $c =~ /usememos\/memos\/store/;
            for my $ent (@ENTITIES) {
                if ($c =~ /\bstore\.$ent\b/) {
                    $refs{$ent}{$pkg} = 1;
                }
            }
        }
    }
    closedir $dh;
}
walk($REPO);

my @ranked = sort { scalar(keys %{$refs{$b}}) <=> scalar(keys %{$refs{$a}}) } @ENTITIES;
print "=== Ranked ===\n";
for my $ent (@ranked) {
    my @pkgs = sort keys %{$refs{$ent}};
    next unless @pkgs;
    print "$ent: ", scalar(@pkgs), "\n";
    print "  - $_\n" for @pkgs;
    print "\n";
}
'

